import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 45 Of men and galaxies","description":"学习 no more than 与 not more than，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 45 Of men and galaxies","description":"学习 no more than 与 not more than，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 no more than 与 not more than，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 44 Patterns of culture","link":"/life/english/new-concept/book-4/unit-06/lesson-044"},"next":{"text":"第四册：流利英语 · Lesson 46 Hobbies","link":"/life/english/new-concept/book-4/unit-06/lesson-046"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 44 Patterns of culture","link":"/life/english/new-concept/book-4/unit-06/lesson-044"},"next":{"text":"第四册：流利英语 · Lesson 46 Hobbies","link":"/life/english/new-concept/book-4/unit-06/lesson-046"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-045.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-045.md"}'),i={name:"life/english/new-concept/book-4/unit-06/lesson-045.md"};function r(s,e,l,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-45-of-men-and-galaxies" tabindex="-1">第四册：流利英语 · Lesson 45 Of men and galaxies <a class="header-anchor" href="#第四册-流利英语-·-lesson-45-of-men-and-galaxies" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 45 Of men and galaxies&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>标题来自讨论人类与科学的作品，本课伴读聚焦人类竞争、知识增长和科学社会影响，不把它误当成星系距离课。阅读时辨认作者对科学力量与社会判断的看法，区分历史性议论和已证实事实。数量表达训练以信息、实验和决策为场景，注意数字边界与修辞强调。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>competition</td><td>/ˌkɒmpəˈtɪʃən/</td><td>n.</td><td>竞争</td><td>competition for resources</td></tr><tr><td>knowledge</td><td>/ˈnɒlɪdʒ/</td><td>n.</td><td>知识</td><td>the growth of knowledge</td></tr><tr><td>influence</td><td>/ˈɪnfluəns/</td><td>n.</td><td>影响</td><td>scientific influence</td></tr><tr><td>responsibility</td><td>/rɪˌspɒnsəˈbɪləti/</td><td>n.</td><td>责任</td><td>social responsibility</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put into practice — 将知识付诸实践</li><li>put into perspective — 放入适当背景理解</li></ul><h2 id="语法讲解-no-more-than-与-not-more-than" tabindex="-1">语法讲解：no more than 与 not more than <a class="header-anchor" href="#语法讲解-no-more-than-与-not-more-than" aria-label="Permalink to &quot;语法讲解：no more than 与 not more than&quot;">​</a></h2><p>more than 表超过；not more than 表不超过，是数量上限；no more than 常表示“仅仅”，带有数量少的评价，也可在明确数量语境中表达上限。no less than 常带“竟有”或“不少于”的强调，需看语境。阅读有关科学影响的数量论证时，先把数学边界写出来，再判断修辞语气；少量信息可能带来重大影响是论点，不能仅靠数字修辞代替证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The summary contained no more than three pages, yet it raised questions the committee had overlooked.</p></blockquote><p>摘要仅有三页，却提出了委员会此前忽略的问题。</p><p>no more than 强调篇幅很短；yet 连接篇幅与作用的反差；had overlooked 表忽略先于摘要提出问题。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>not more than 10 表 ≤10，不是 &lt;10；上限本身也在允许范围内。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比读 more than、no more than、not more than，重读否定词；再朗读示例中的 yet，听出篇幅虽短但作用值得注意的转折。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The summary contains no more than three pages. It explains a technical possibility but leaves its wider consequences open. Any public decision would also need discussion of costs, responsibilities and competing aims.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评论一份虚构科学摘要：篇幅、提出的问题、社会决策还需要什么。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>以少量文字与广泛影响形成对照，再区分技术可能性与公共判断，不把科学能力直接等同于社会选择。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>not more than 10 是否允许恰好10？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 允许。</p><p><strong>解析：</strong> 意思是不超过10。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中的 no more than 更接近“仅仅”还是“超过”？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 仅仅。</p><p><strong>解析：</strong> 它强调摘要篇幅虽短，却产生了值得注意的作用。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把“超过20个点”译成英语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> more than twenty points</p><p><strong>解析：</strong> more than 表严格超过。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：no more than 与 not more than。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-044">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-046">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
